function generateAutoGame(config) {
  var lang = config.lang || 'es';
  var count = config.count || 10;
  var categories = config.categories || ['science','geography','history','entertainment','arts','sports'];
  var difficulty = config.difficulty || 'mixed';

  var pool = QB.filter(function(q) {
    return categories.indexOf(q.c) !== -1 &&
      (difficulty === 'mixed' || q.d === difficulty);
  });

  for (var i = pool.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = pool[i]; pool[i] = pool[j]; pool[j] = tmp;
  }

  if (categories.length > 1) {
    var perCat = Math.ceil(count / categories.length);
    var selected = [];
    categories.forEach(function(cat) {
      var catQ = pool.filter(function(q){ return q.c === cat; });
      selected = selected.concat(catQ.slice(0, perCat));
    });
    for (var i = selected.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var tmp = selected[i]; selected[i] = selected[j]; selected[j] = tmp;
    }
    pool = selected.slice(0, count);
  } else {
    pool = pool.slice(0, count);
  }

  return pool.map(function(item) {
    var loc = item[lang] || item.es;
    return {
      text: loc.t,
      options: { A: loc.o[0], B: loc.o[1], C: loc.o[2], D: loc.o[3] },
      correct: loc.r,
      type: 'multiple',
      time: 20,
      category: item.c,
      difficulty: item.d
    };
  });
}
